/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
const kb = JSON.parse(readFileSync('server/kristy_perimeter_kb.json', 'utf8'));
const base = JSON.parse(execFileSync('git', ['show', 'c6d3ff2:server/kristy_perimeter_kb.json'], { maxBuffer: 64 << 20 }));
assert.deepEqual(kb, base);
const pin = readFileSync('server/test/acceptance/twoLinePin.js', 'utf8');
const idsFor = n => [...pin.match(new RegExp("'`export const CLEAN_PICK_${n} = new Set'"\\\\(\\\\[(["'^'"\\\\]]+)\\\\]\\\\);"'`))[1].matchAll(/'"'(["'^'"']+)'/g)].map(m => m[1]);
const acceptance = readFileSync('server/test/acceptance/cleanPick6.test.js', 'utf8');
const ids = [...acceptance.matchAll(/"'^  (pick_'"\\w+): \\{ decision:/gm)].map(m => m[1]);
for (const id of ids) console.log(id + ': ' + base.entries.find(e => e.id === id).decision);
const later1 = readFileSync('server/test/acceptance/cleanPick1.test.js', 'utf8').match(/const LATER = new Set\\(\\[([\\s\\S]*?)\\]\\);/)[1];
const cp1exclude = [...idsFor(1), ...[...later1.matchAll(/'(["'^'"']+)'/g)].map(m => m[1]), ...ids];
console.log('CP1 outside:', kb.entries.filter(e => "'!cp1exclude.includes(e.id)).length);
for (const n of [2, 3, 4, 5]) {
  const exclude = new Set([...Array.from({length: 6 - n}, (_, i) => idsFor(i + n)).flat(), ...ids, ...(n === 2 ? ['"'label_organic_scope'] : [])]);
  console.log("'`CP${n} outside:`, kb.entries.filter(e => !exclude.has(e.id)).length);
}
console.log('"'CP6 outside:', kb.entries.length - ids.length);
console.log('Batch aliases:', kb.entries.filter(e => ids.includes(e.id)).flatMap(e => e.aliases).length);
console.log('Corpus bare/organic queries:', kb.entries.filter(e => e.kind === 'pick').flatMap(e => e.aliases).length * 2);
NODE"

/bin/zsh -lc "node --input-type=module <<'NODE'
import { mkdtempSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';
const scratch = mkdtempSync(join(process.cwd(), '.clean-pick-6-test-'));
try {
  const result = spawnSync('npm', ['test'], {
    encoding: 'utf8',
    env: { ...process.env, TMPDIR: scratch, npm_config_cache: join(scratch, 'npm-cache') },
    maxBuffer: 64 << 20,
  });
  const output = "'`${result.stdout || '"''}\\n"'${result.stderr || '"''}"'`;
  const lines = output.split('"'\\n');
  console.log(lines.filter(line => /"'^> |''^ℹ|''^# (tests|suites|pass|fail|cancelled|skipped|todo|duration_ms)|''^✖|''^not ok/.test(line)).join('"'\\n'));
  if (result.status "'!== 0) console.log(output.slice(-20000));
  if (result.error) console.error(result.error.message);
  console.log(`npm test exit: ${result.status}; temporary test files cleaned up`);
  process.exitCode = result.status ?? 1;
} finally {
  rmSync(scratch, { recursive: true, force: true });
}
NODE'

/bin/zsh -lc "node --input-type=module <<'NODE'
import { readFileSync } from 'node:fs';
import { matchItemToCard, matchItemToPick } from './server/lib/listMatch.js';
import { words } from './server/lib/counterCardLint.js';
const kb = JSON.parse(readFileSync('server/kristy_perimeter_kb.json', 'utf8'));
const acceptance = readFileSync('server/test/acceptance/cleanPick6.test.js', 'utf8');
const ids = [...acceptance.matchAll(/"'^  (pick_'"\\w+): \\{ decision:/gm)].map(m => m[1]);
const batch = kb.entries.filter(e => ids.includes(e.id));
const cardRows = batch.flatMap(e => e.aliases.map(alias => "'`organic ${alias}`)).map(q => ({ query: q, card: matchItemToCard(q)?.slug })).filter(row => row.card);
console.log(JSON.stringify({ organicAliasCardRows: cardRows, wordCounts: Object.fromEntries(batch.map(e => [e.id, words(e.decision)])) }, null, 2));
for (const q of ['"'sweet corn', 'ears of corn', 'yellow squash', 'coriander leaves', 'sweet basil', 'snow peas', 'celery hearts', 'bunch of celery']) {
  console.log(JSON.stringify({ query: q, pick: matchItemToPick(q)?.id, organicPick: matchItemToPick("'`organic ${q}`)?.id, card: matchItemToCard(q) }));
}
NODE'
